//! ASCII boot animation, drawn inside the TUI until the first key press or the end of the clip.
//! Frames are generated by `scripts/make_boot_ascii.sh` into `assets/boot.txt`
//! (frames separated by a line containing only a form feed). Blank characters
//! are the transparent background, so only the bright parts of the video show.
//!
//! While the clip runs, a dotted ring surrounds it. When the clip stops (key press or
//! end of clip), the video disappears at once and the ring erodes away over `ERODE`.

use std::time::{Duration, Instant};

const BOOT_FRAMES: &str = include_str!("../assets/boot.txt");
const FPS: u64 = 24;
const FRAME_MICROS: u64 = 1_000_000 / FPS;
/// How long the dotted ring takes to fully disappear after the clip stops.
const ERODE: Duration = Duration::from_millis(900);
/// Redraw interval while the ring erodes (no frame boundaries to wait for).
const ERODE_TICK: Duration = Duration::from_millis(33);

/// Playback state of the boot clip. Frame index is derived from elapsed time,
/// so a slow redraw skips frames instead of slowing the clip down.
pub struct BootAnimation {
    frames: Vec<&'static str>,
    /// Width and height in cells of every frame (all frames share one size).
    size: (u16, u16),
    started: Instant,
}

impl BootAnimation {
    /// Returns `None` when `MINERVE_NO_BOOT` is set or the asset has no frames.
    pub fn start() -> Option<Self> {
        if std::env::var_os("MINERVE_NO_BOOT").is_some() {
            return None;
        }
        let frames: Vec<&'static str> = BOOT_FRAMES
            .split("\n\u{c}\n")
            .filter(|frame| !frame.is_empty())
            .collect();
        let first = *frames.first()?;
        let width = first.lines().map(|l| l.chars().count()).max().unwrap_or(0) as u16;
        let height = first.lines().count() as u16;
        Some(Self {
            frames,
            size: (width, height),
            started: Instant::now(),
        })
    }

    /// Width and height in cells of the video.
    pub fn size(&self) -> (u16, u16) {
        self.size
    }

    fn frame_index(&self) -> usize {
        (self.started.elapsed().as_micros() / FRAME_MICROS as u128) as usize
    }

    /// When the clip stopped: the key press, or the natural end of the last frame.
    fn ended_at(&self) -> Option<Instant> {
        let natural_end = self.started + Duration::from_micros(self.frames.len() as u64 * FRAME_MICROS);
        (Instant::now() >= natural_end).then_some(natural_end)
    }

    /// True while the video is playing (not stopped and not past its last frame).
    pub fn is_playing(&self) -> bool {
        self.ended_at().is_none()
    }

    /// The video frame to show now, or `None` once the clip has stopped or ended.
    pub fn current_frame(&self) -> Option<&'static str> {
        if !self.is_playing() {
            return None;
        }
        self.frames.get(self.frame_index()).copied()
    }

    /// Erosion progress of the ring after the clip has ended: 0.0 just after the stop,
    /// 1.0 when fully gone. `None` while the clip is still playing.
    pub fn erosion(&self) -> Option<f32> {
        let ended = self.ended_at()?;
        Some((ended.elapsed().as_secs_f32() / ERODE.as_secs_f32()).min(1.0))
    }

    /// Progress of the dash sweep. It starts at the midpoint of the clip and ends together with
    /// the erosion (`ERODE` after the video stops), so the caption is gone when the boot screen drops.
    /// `None` before the midpoint.
    pub fn sweep_progress(&self) -> Option<f32> {
        let total = self.frames.len() as u64 * FRAME_MICROS;
        let start = self.started + Duration::from_micros(total / 2);
        let end = self.started + Duration::from_micros(total) + ERODE;
        let now = Instant::now();
        if now < start {
            return None;
        }
        Some(((now - start).as_secs_f32() / (end - start).as_secs_f32()).min(1.0))
    }

    /// True once the dash sweep has completed: the boot screen can be dropped.
    pub fn is_finished(&self) -> bool {
        self.sweep_progress().is_some_and(|p| p >= 1.0)
    }

    /// How long until the next redraw is needed: the next frame boundary while playing,
    /// a short tick while eroding.
    pub fn time_to_next_frame(&self) -> Duration {
        if !self.is_playing() {
            return ERODE_TICK;
        }
        let next = (self.frame_index() as u64 + 1) * FRAME_MICROS;
        let elapsed = self.started.elapsed().as_micros() as u64;
        Duration::from_micros(next.saturating_sub(elapsed))
    }
}
